import math
def control(obs):
    hitch = float(obs.get('hitch_deg', 0.0))
    route = obs.get('route') or {}
    bearing = float(route.get('bearing_deg', 0.0))
    lm = obs.get('local_map') or {}
    left = lm.get('left_rail') or []
    right = lm.get('right_rail') or []
    # Estimate the course center's lateral position a few metres behind the trailer.
    pairs = []
    for a in left:
        u, v = float(a[0]), float(a[1])
        if 1.0 <= u <= 5.5:
            b = min(right, key=lambda p: abs(float(p[0])-u)) if right else None
            if b is not None and abs(float(b[0])-u) < 0.8:
                pairs.append((u, (v+float(b[1]))/2.0))
    lateral = sum(v for _, v in pairs)/len(pairs) if pairs else 0.0
    # Positive hitch needs positive steering to straighten while reversing.
    steer = 1.25*hitch - 0.75*bearing - 9.0*lateral
    steer = max(-24.0, min(24.0, steer))
    return (steer, -0.8, 180.0)

