import math
def control(obs):
    m=obs.get('local_map',{})
    L=m.get('left_rail',[])
    R=m.get('right_rail',[])
    pairs=[]
    for u,v in L:
        if 2.5 <= u <= 8 and R:
            b=min(R,key=lambda p: abs(p[0]-u))
            if abs(b[0]-u)<1.0:
                pairs.append((u,(v+b[1])*0.5))
    if pairs:
        u,c=min(pairs,key=lambda p: abs(p[0]-5.0))
        e=c
        near=[p for p in pairs if p[0]<u]
        if near:
            un,cn=min(near,key=lambda p: abs(p[0]-(u-1.5)))
            slope=(c-cn)/max(.5,u-un)
        else:
            slope=0.0
        path=-math.degrees(math.atan2(e,max(2.0,u)))-18.0*math.degrees(math.atan(slope))
    else:
        path=0.0
    h=float(obs.get('hitch_deg',0.0))
    steer=max(-22.0,min(22.0,path+0.65*h))
    return (steer,-0.75,180.0)

