import math
def control(obs):
    h=float(obs.get('hitch_deg',0.0))
    status=obs.get('status','')
    # Pull forward until hitch is nearly straight, using forward steering to reduce angle.
    if abs(h)>5 or status in ('PINNED','JACKKNIFED'):
        steer=max(-30.0,min(30.0,-1.0*h))
        return (steer,1.0,180.0)
    # Resume reverse; route/map centering with conservative speed.
    m=obs.get('local_map',{})
    L=m.get('left_rail',[]); R=m.get('right_rail',[])
    pairs=[]
    for u,v in L:
        if 2<=u<=7 and R:
            b=min(R,key=lambda p:abs(p[0]-u))
            if abs(b[0]-u)<1.0:pairs.append((u,(v+b[1])*0.5))
    if pairs:
        u,c=min(pairs,key=lambda p:abs(p[0]-4.0))
        path=-math.degrees(math.atan2(c,max(2,u)))
    else:path=0.0
    h=float(obs.get('hitch_deg',0.0))
    return (max(-18,min(18,path+0.55*h)),-0.35,180.0)

