import math

def control(obs):
    lm = obs.get('local_map', {})
    left = lm.get('left_rail', [])
    right = lm.get('right_rail', [])
    samples = []
    for p in left:
        u, v = p[0], p[1]
        if u >= 0:
            q = min(right, key=lambda r: abs(r[0]-u), default=None)
            if q is not None and abs(q[0]-u) < 2.0:
                samples.append((u, (v+q[1])*0.5))
    samples.sort()
    target = min((x for x in samples if x[0] >= 8), key=lambda x: x[0], default=None)
    if target is None and samples:
        target = min(samples, key=lambda x: abs(x[0]-8))
    bearing = obs.get('route', {}).get('bearing_deg', 0.0)
    if target is not None:
        local_bearing = math.degrees(math.atan2(target[1], max(target[0], 1.0)))
        bearing = 0.65 * bearing + 0.35 * local_bearing
    hitch = obs.get('hitch_deg', 0.0)
    steer = max(-24.0, min(24.0, -1.25 * bearing + 1.05 * hitch))
    return (steer, -0.75, 180.0)

